```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char *p = (char *)malloc((size_t)n + 1);
    if (p == NULL) return 0;
    if (scanf("%s", p) != 1) {
        free(p);
        return 0;
    }

    for (int k = 1; k <= n / 2; k++) {
        if (n % k != 0) continue;

        int base[26] = {0};
        for (int i = 0; i < k; i++) {
            base[p[i] - 'a']++;
        }

        int valid = 1;
        for (int start = k; start < n && valid; start += k) {
            int current[26] = {0};
            for (int i = start; i < start + k; i++) {
                current[p[i] - 'a']++;
            }
            if (memcmp(base, current, sizeof(base)) != 0) {
                valid = 0;
            }
        }

        if (valid) {
            p[k] = '\0';
            printf("%s\n", p);
            free(p);
            return 0;
        }
    }

    printf("*\n");
    free(p);
    return 0;
}
```

